package store

import (
	"context"
	"testing"
	"time"
)

// TestMetadataSourcePrefs covers the metadata_source_prefs control table
// (plugin-title-enrichment 1.1; scenarios ae5cb6d3f0337e7f override and
// 52adf392d8ac83f5 clear-to-inherit): the upsert holds exactly ONE row per
// (module_id, library_id, plugin_id) triple and refreshes the stamp, the
// batched list returns module-scope rows plus the requested library rows in
// one read, and deleting a library gate reverts that scope to the
// module-scope row on the next read (absent row deletes are a no-op).
func TestMetadataSourcePrefs(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)

	libA, err := s.CreateLibrary(ctx, "serial", "/media/prefs-a", "A")
	if err != nil {
		t.Fatalf("CreateLibrary A: %v", err)
	}
	libB, err := s.CreateLibrary(ctx, "serial", "/media/prefs-b", "B")
	if err != nil {
		t.Fatalf("CreateLibrary B: %v", err)
	}

	t.Run("upsert_roundtrip_and_overwrite", func(t *testing.T) {
		if err := s.UpsertMetadataSourcePref(ctx, MetadataSourcePref{
			ModuleID: "serial", LibraryID: 0, PluginID: "shikimori", Enabled: false,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref module scope: %v", err)
		}
		got, err := s.ListMetadataSourcePrefs(ctx, "serial", nil)
		if err != nil {
			t.Fatalf("ListMetadataSourcePrefs: %v", err)
		}
		if len(got) != 1 || got[0].ModuleID != "serial" || got[0].LibraryID != 0 ||
			got[0].PluginID != "shikimori" || got[0].Enabled {
			t.Fatalf("after first upsert = %+v, want one module-scope shikimori row disabled", got)
		}
		firstStamp := got[0].UpdatedAt
		if firstStamp == "" {
			t.Fatalf("updated_at = %q, want the write-time stamp", firstStamp)
		}

		time.Sleep(2 * time.Millisecond) // ensure a strictly later updated_at stamp
		if err := s.UpsertMetadataSourcePref(ctx, MetadataSourcePref{
			ModuleID: "serial", LibraryID: 0, PluginID: "shikimori", Enabled: true,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref overwrite: %v", err)
		}
		got, err = s.ListMetadataSourcePrefs(ctx, "serial", nil)
		if err != nil {
			t.Fatalf("ListMetadataSourcePrefs after overwrite: %v", err)
		}
		if len(got) != 1 {
			t.Fatalf("rows after overwrite = %d, want 1 (upsert, not append)", len(got))
		}
		if !got[0].Enabled {
			t.Fatalf("enabled = false, want true (latest write wins)")
		}
		if got[0].UpdatedAt == "" || got[0].UpdatedAt == firstStamp {
			t.Fatalf("updated_at = %q, want refreshed (first %q)", got[0].UpdatedAt, firstStamp)
		}

		// Restore the module-scope gate the later subtests assume.
		if err := s.UpsertMetadataSourcePref(ctx, MetadataSourcePref{
			ModuleID: "serial", LibraryID: 0, PluginID: "shikimori", Enabled: false,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref restore: %v", err)
		}
	})

	// Scenario ae5cb6d3f0337e7f: a library gate overrides the module gate —
	// the batched read surfaces both rows so the consumer resolves libA
	// enabled while every other library (libB: no row of its own) falls back
	// to the module-scope row.
	t.Run("library_gate_overrides_module_gate", func(t *testing.T) {
		if err := s.UpsertMetadataSourcePref(ctx, MetadataSourcePref{
			ModuleID: "serial", LibraryID: libA, PluginID: "shikimori", Enabled: true,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref library scope: %v", err)
		}

		got, err := s.ListMetadataSourcePrefs(ctx, "serial", []int64{libA, libB})
		if err != nil {
			t.Fatalf("ListMetadataSourcePrefs batched: %v", err)
		}
		if len(got) != 2 {
			t.Fatalf("batched list = %+v, want 2 rows (module scope + libA)", got)
		}
		// Ordered library_id then plugin_id: the module-scope row (0) first.
		if got[0].LibraryID != 0 || got[0].Enabled {
			t.Fatalf("row[0] = %+v, want module scope (library_id 0) disabled", got[0])
		}
		if got[1].LibraryID != libA || !got[1].Enabled {
			t.Fatalf("row[1] = %+v, want libA enabled (the override)", got[1])
		}

		// nil library ids → module-scope rows only.
		moduleOnly, err := s.ListMetadataSourcePrefs(ctx, "serial", nil)
		if err != nil {
			t.Fatalf("ListMetadataSourcePrefs module-only: %v", err)
		}
		if len(moduleOnly) != 1 || moduleOnly[0].LibraryID != 0 {
			t.Fatalf("module-only list = %+v, want only the library_id 0 row", moduleOnly)
		}
	})

	// Scenario 52adf392d8ac83f5: clearing a library gate reverts to inherit —
	// the row is gone on the next read, the module-scope row untouched, and
	// clearing an absent row is a no-op.
	t.Run("clear_library_gate_reverts_to_inherit", func(t *testing.T) {
		if err := s.DeleteMetadataSourcePref(ctx, "serial", libA, "shikimori"); err != nil {
			t.Fatalf("DeleteMetadataSourcePref: %v", err)
		}
		got, err := s.ListMetadataSourcePrefs(ctx, "serial", []int64{libA, libB})
		if err != nil {
			t.Fatalf("ListMetadataSourcePrefs after clear: %v", err)
		}
		if len(got) != 1 || got[0].LibraryID != 0 {
			t.Fatalf("list after clear = %+v, want only the module-scope row", got)
		}
		if err := s.DeleteMetadataSourcePref(ctx, "serial", libA, "shikimori"); err != nil {
			t.Fatalf("DeleteMetadataSourcePref absent row: %v (clear must be idempotent)", err)
		}
	})

	t.Run("unknown_module_lists_empty", func(t *testing.T) {
		got, err := s.ListMetadataSourcePrefs(ctx, "image", []int64{libA})
		if err != nil {
			t.Fatalf("ListMetadataSourcePrefs image: %v", err)
		}
		if got == nil || len(got) != 0 {
			t.Fatalf("list = %v, want non-nil empty slice (INV-empty-not-nil)", got)
		}
	})
}
